typedef float vm_num_t;

class stringx
{
public:
  stringx();
  explicit stringx(int);
  stringx& operator=(const stringx&);
};

typedef stringx* vm_str_t;

class vm_stack
{
public:
  void pop(int);
  char* get_SP() const;
  bool push(const char*, int);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

#define MAX_STATIC_TO_STR_STRINGS 30
static stringx script_strings[MAX_STATIC_TO_STR_STRINGS];
static int script_strings_cnt;

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( "script stack overflow" )
#define SLF_DONE return true

void error(const char*);

class slf_to_str_int_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_num_t n;
  };

  virtual bool operator()(vm_stack& stack, entry_t entry);
};

bool slf_to_str_int_t::operator()(vm_stack &stack, entry_t entry)
{
  SLF_PARMS;

  script_strings[script_strings_cnt] = stringx(((int)parms->n));
  vm_str_t result = &script_strings[script_strings_cnt];
  ++script_strings_cnt;
  if(script_strings_cnt >= MAX_STATIC_TO_STR_STRINGS)
    script_strings_cnt = 0;

  SLF_RETURN;
  SLF_DONE;
}
